// Auto-generated in-app user manual page — styled to match the platform (Poppins, glass, sidebar-dark).
// Content mirrors docs/user-manual/index.html; images are served from client/public/manual-images/.
import { Link } from 'react-router-dom'

const CSS = ":root{\n    --blue:#2563eb; --blue-700:#1d4ed8; --ink:#0f172a; --muted:#64748b; --faint:#94a3b8;\n    --radius:1rem;\n    --glass-bd:1px solid rgba(255,255,255,.6);\n    --glass-sh:0 20px 25px -5px rgba(15,23,42,.05),0 8px 10px -6px rgba(15,23,42,.05);\n  }\n  *{box-sizing:border-box}\n.manual-page{scroll-behavior:smooth}\n.manual-page{\n    margin:0;min-height:100vh;color:var(--ink);line-height:1.6;-webkit-font-smoothing:antialiased;\n    font-family:'Poppins',ui-sans-serif,system-ui,-apple-system,sans-serif;\n    background:\n      radial-gradient(38rem 38rem at 105% -8%, rgba(37,99,235,.20), transparent 60%),\n      radial-gradient(34rem 34rem at -8% 18%, rgba(99,102,241,.18), transparent 60%),\n      radial-gradient(30rem 30rem at 55% 118%, rgba(14,165,233,.16), transparent 60%),\n      linear-gradient(135deg,#eef2ff 0%,#f8fafc 50%,#eff6ff 100%);\n    background-attachment:fixed;\n  }\n  @keyframes manualFadeInUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n\n  .layout{display:grid;grid-template-columns:264px 1fr;gap:0;max-width:1360px;margin:0 auto}\n\n  /* TOC sidebar — mirrors the app's .sidebar-dark */\n  aside{position:sticky;top:0;align-self:start;height:100vh;overflow-y:auto;padding:26px 16px;\n    background:\n      radial-gradient(26rem 20rem at 10% -5%, rgba(59,130,246,.28), transparent 60%),\n      linear-gradient(180deg,#131b31 0%,#0d1424 55%,#0a0f1d 100%);\n    backdrop-filter:blur(22px) saturate(160%);-webkit-backdrop-filter:blur(22px) saturate(160%);\n    border-right:1px solid rgba(255,255,255,.08)}\n  aside .brand{display:flex;align-items:center;gap:10px;color:#fff;font-weight:600;font-size:18px;letter-spacing:-.01em;padding:0 10px}\n  aside .brand svg{stroke:#fff}\n  aside .tag{font-size:12px;color:#7c8aa5;margin:2px 0 20px 42px}\n  aside nav{display:flex;flex-direction:column;gap:2px}\n  aside nav a{color:#cbd5e1;text-decoration:none;font-size:14px;font-weight:500;padding:8px 12px;border-radius:12px;\n    transition:background-color .2s,color .2s,transform .2s}\n  aside nav a:hover{background:rgba(255,255,255,.10);color:#fff;transform:translateX(2px)}\n  aside nav a.section{margin-top:16px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#64748b;font-weight:600;pointer-events:none;padding-bottom:2px}\n  aside .foot{margin-top:24px;padding:16px 12px 0;border-top:1px solid rgba(255,255,255,.10);font-size:12px;color:#7c8aa5}\n\n  main{padding:44px 48px;min-width:0;animation:manualFadeInUp .4s cubic-bezier(.16,1,.3,1) both}\n\n  .hero{margin-bottom:10px}\n  .hero .kicker{color:var(--blue);font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-size:12px}\n  h1{font-size:34px;line-height:1.15;margin:6px 0 10px;letter-spacing:-.02em;font-weight:700;color:var(--ink)}\n  .lede{font-size:17px;color:var(--muted);max-width:68ch}\n  h2{font-size:24px;margin:48px 0 6px;letter-spacing:-.01em;font-weight:700;color:var(--ink);scroll-margin-top:20px}\n  h3{font-size:17px;margin:24px 0 8px;font-weight:600;color:var(--ink)}\n  p{margin:10px 0}\n  section{border-top:1px solid rgba(148,163,184,.22);padding-top:10px}\n  section:first-of-type{border-top:none}\n  a{color:var(--blue-700);text-decoration:none}\n  a:hover{text-decoration:underline}\n  b{color:var(--ink)}\n  i{color:inherit}\n\n  .meta{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0 8px}\n  .pill{font-size:12px;font-weight:500;color:var(--blue-700);background:#eff6ff;border-radius:999px;padding:5px 12px}\n\n  /* Frosted-glass surface used by figures, cards and tables (matches .glass) */\n  figure{margin:22px 0;border-radius:var(--radius);overflow:hidden;\n    background:rgba(255,255,255,.55);backdrop-filter:blur(16px) saturate(160%);-webkit-backdrop-filter:blur(16px) saturate(160%);\n    border:var(--glass-bd);box-shadow:var(--glass-sh)}\n  figure img{display:block;width:100%;height:auto}\n  figcaption{font-size:13px;color:var(--muted);padding:10px 16px;border-top:1px solid rgba(255,255,255,.5)}\n\n  .legend{list-style:none;margin:14px 0 0;padding:0;display:grid;gap:10px}\n  .legend li{display:grid;grid-template-columns:30px 1fr;gap:12px;align-items:start}\n  .badge{width:26px;height:26px;border-radius:50%;color:#fff;font-weight:600;font-size:13px;\n    display:flex;align-items:center;justify-content:center;\n    background:linear-gradient(to bottom,#3b82f6,#2563eb);box-shadow:0 8px 12px -4px rgba(37,99,235,.35)}\n  .legend li b{color:var(--ink)}\n\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n  .card{border-radius:var(--radius);padding:18px 20px;\n    background:rgba(255,255,255,.55);backdrop-filter:blur(16px) saturate(160%);-webkit-backdrop-filter:blur(16px) saturate(160%);\n    border:var(--glass-bd);box-shadow:var(--glass-sh)}\n  .card h3{margin-top:0}\n  .card p{margin:6px 0;font-size:14.5px}\n\n  .callout{border-left:3px solid var(--blue);border-radius:12px;padding:14px 16px;margin:18px 0;\n    background:rgba(239,246,255,.7);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}\n  .callout.warn{border-color:#d97706;background:rgba(255,251,235,.78)}\n  .callout.note{border-color:#94a3b8;background:rgba(241,245,249,.78)}\n  .callout p{margin:4px 0}\n  .callout .h{font-weight:600;display:block;margin-bottom:2px;color:var(--ink)}\n\n  /* Definition tables rendered as glass cards */\n  table.def{width:100%;border-collapse:separate;border-spacing:0;margin:16px 0;font-size:14px;\n    background:rgba(255,255,255,.5);backdrop-filter:blur(16px) saturate(160%);-webkit-backdrop-filter:blur(16px) saturate(160%);\n    border:var(--glass-bd);border-radius:var(--radius);overflow:hidden;box-shadow:var(--glass-sh)}\n  table.def th,table.def td{text-align:left;padding:11px 16px;border-bottom:1px solid rgba(148,163,184,.18);vertical-align:top;line-height:1.5}\n  table.def tr:last-child td{border-bottom:none}\n  table.def th{background:rgba(255,255,255,.45);font-size:11px;letter-spacing:.04em;text-transform:uppercase;color:#334155;font-weight:600}\n  code{background:#eff6ff;color:#1d4ed8;padding:1px 6px;border-radius:6px;font-size:13px;\n    font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}\n\n  .steps{counter-reset:step;list-style:none;padding:0;margin:14px 0}\n  .steps li{position:relative;padding:6px 0 6px 40px;margin:6px 0}\n  .steps li::before{counter-increment:step;content:counter(step);position:absolute;left:0;top:3px;\n    width:26px;height:26px;border-radius:50%;color:#fff;font-size:13px;font-weight:600;\n    display:flex;align-items:center;justify-content:center;\n    background:linear-gradient(180deg,#131b31,#0d1424);box-shadow:0 6px 10px -3px rgba(15,23,42,.3)}\n\n  kbd{background:linear-gradient(180deg,#131b31,#0d1424);color:#fff;border-radius:7px;padding:2px 8px;font-size:12px;font-weight:600}\n  .tag-green{color:#16a34a;font-weight:600}\n  .tag-red{color:#dc2626;font-weight:600}\n  .tag-amber{color:#b45309;font-weight:600}\n\n  footer{margin-top:56px;padding-top:20px;border-top:1px solid rgba(148,163,184,.22);color:var(--muted);font-size:13px}\n\n  @media (max-width:960px){\n    .layout{grid-template-columns:1fr}\n    aside{position:static;height:auto;overflow:visible;border-right:none;border-bottom:1px solid rgba(255,255,255,.08)}\n    aside nav{display:grid;grid-template-columns:1fr 1fr;gap:2px 10px}\n    aside nav a.section{grid-column:1 / -1}\n    main{padding:26px 20px}\n    .grid2{grid-template-columns:1fr}\n    h1{font-size:28px}\n  }\n  @media print{\n    aside{display:none}.layout{grid-template-columns:1fr;max-width:none}\n    main{padding:0;animation:none}figure,section,.card{break-inside:avoid}\n  }\n  .manual-back{position:fixed;top:16px;right:18px;z-index:60;display:inline-flex;align-items:center;gap:7px;\n    padding:9px 15px;border-radius:12px;font-size:13px;font-weight:500;color:#334155;text-decoration:none;\n    background:rgba(255,255,255,.72);backdrop-filter:blur(22px) saturate(170%);-webkit-backdrop-filter:blur(22px) saturate(170%);\n    border:1px solid rgba(255,255,255,.7);box-shadow:0 10px 20px -6px rgba(15,23,42,.18)}\n  .manual-back:hover{background:rgba(255,255,255,.9);text-decoration:none}\n  .manual-back svg{stroke:#334155}\n  @media (max-width:960px){.manual-back{top:12px;right:12px;padding:8px 12px;font-size:12px}}\n  @media print{.manual-back{display:none}}"

const BODY = "<div class=\"layout\">\n  <aside>\n    <div class=\"brand\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 19V6l8 6 8-6v13\"/></svg>\n      Platform-CRM\n    </div>\n    <p class=\"tag\">User Manual</p>\n    <nav>\n      <a href=\"#intro\">Overview</a>\n      <a href=\"#concepts\">Key concepts</a>\n      <a href=\"#navigation\">Getting around</a>\n      <a href=\"#controls\">Shared controls</a>\n      <a class=\"section\">Pages</a>\n      <a href=\"#dashboard\">Dashboard</a>\n      <a href=\"#daily-sheet\">Daily Sheet</a>\n      <a href=\"#buyers\">Buyers</a>\n      <a href=\"#campaigns\">Campaigns</a>\n      <a href=\"#vendors\">Vendors</a>\n      <a href=\"#portal-expenses\">Portal Expenses</a>\n      <a href=\"#complete-report\">Complete Report</a>\n      <a href=\"#attendance\">Attendance</a>\n      <a href=\"#queues\">Queues</a>\n      <a href=\"#review\">Review</a>\n      <a href=\"#staff\">Staff Management</a>\n      <a class=\"section\">Reference</a>\n      <a href=\"#auth\">Accounts &amp; access</a>\n      <a href=\"#faq\">Tips &amp; FAQ</a>\n    </nav>\n    <div class=\"foot\">Revised 10 Sep 2026<br>Screens use sample data.</div>\n  </aside>\n\n  <main>\n    <div class=\"hero\" id=\"intro\">\n      <div class=\"kicker\">Platform-CRM</div>\n      <h1>User Manual</h1>\n      <p class=\"lede\">Platform-CRM is a pay-per-Lead / Lead-forwarding CRM. Your team records the daily\n      Lead volumes for <b>buyers</b> (the revenue side — Leads sold and forwarded to customers) and\n      <b>campaigns</b> (the cost side — the media buying that sources those Leads). The gap between the\n      two is your <b>profit</b>. Alongside that it runs the team side — attendance, queue coverage, monthly\n      reviews and the staff roster they all share. This guide walks through every page and the controls\n      you'll use daily.</p>\n      <div class=\"meta\">\n        <span class=\"pill\">11 working pages</span>\n        <span class=\"pill\">Revenue &amp; cost tracking</span>\n        <span class=\"pill\">Live dashboard</span>\n        <span class=\"pill\">Team &amp; attendance</span>\n        <span class=\"pill\">CSV / PDF reports</span>\n      </div>\n    </div>\n\n    <!-- CONCEPTS -->\n    <section id=\"concepts\">\n      <h2>Key concepts</h2>\n      <p>A few terms recur across every page. Understanding them makes the whole app read at a glance.</p>\n      <table class=\"def\">\n        <thead><tr><th>Term</th><th>What it means</th></tr></thead>\n        <tbody>\n          <tr><td><b>Buyer</b></td><td>A customer who <i>buys</i> forwarded Leads from you — the <b>revenue</b> side. Buyers have a short code such as <code>RTG 04</code> or <code>L48</code>.</td></tr>\n          <tr><td><b>Campaign</b></td><td>A media-buying campaign that <i>sources</i> Leads — the <b>cost</b> side. Campaigns have codes like <code>C-05</code> and a traffic <b>destination / source</b> such as <code>XXD</code>.</td></tr>\n          <tr><td><b>Answered / Missed</b></td><td>Leads that connected vs. Leads that rang out, for a single day and destination.</td></tr>\n          <tr><td><b>Counted</b></td><td>The billable number of Leads for that row (answered plus any counted replacements).</td></tr>\n          <tr><td><b>Rate</b></td><td>The price per counted Lead, in dollars.</td></tr>\n          <tr><td><b>Total&nbsp;bill</b></td><td>Calculated automatically as <code>Counted × Rate</code>. You never type this — it updates as you edit.</td></tr>\n          <tr><td><b>Profit / Margin</b></td><td>Revenue (from buyers) minus Cost (from campaigns). A negative number is shown in <span class=\"tag-red\">red</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout note\"><span class=\"h\">The golden rule</span>\n        <p>Everything you enter lives on the <b>Daily Sheet</b> (revenue) and the <b>Campaigns</b> sheet (cost).\n        The Dashboard, Buyers, and Complete Report pages are all <i>views</i> that summarise those two sheets — you rarely edit them directly.</p>\n      </div>\n    </section>\n\n    <!-- NAVIGATION -->\n    <section id=\"navigation\">\n      <h2>Getting around</h2>\n      <p>The dark sidebar on the left is always visible on desktop. It's how you move between pages; the\n      highlighted item is the page you're on. On a phone, tap the <kbd>☰</kbd> menu icon in the top bar to open it.</p>\n      <div class=\"grid2\">\n        <div class=\"card\">\n          <h3>The eleven pages</h3>\n          <p><b>Dashboard</b> — the at-a-glance performance overview.</p>\n          <p><b>Daily Sheet</b> — enter and review buyer (revenue) Lead records.</p>\n          <p><b>Buyers</b> — a per-buyer monthly summary with editable rates.</p>\n          <p><b>Campaigns</b> — enter and review campaign (cost) Lead records.</p>\n          <p><b>Vendors</b> — per-traffic-source payment ledgers.</p>\n          <p><b>Portal Expenses</b> — monthly provider expense sheet.</p>\n          <p><b>Complete Report</b> — revenue, cost and profit side by side.</p>\n          <p><b>Attendance</b> — team check-in / check-out tracking.</p>\n          <p><b>Queues</b> — who covers which forwarding and camp queues.</p>\n          <p><b>Review</b> — monthly performance and behaviour reviews.</p>\n          <p><b>Staff Management</b> — the staff roster, attendance, leaves and salaries.</p>\n        </div>\n        <div class=\"card\">\n          <h3>Reading a page</h3>\n          <p>Every page opens with a <b>title</b> and short subtitle at the top-left, and its main\n          <b>controls</b> (date range, search, filters) at the top-right.</p>\n          <p>Money is shown in dollars; large counts use thousands separators. Positive changes are\n          <span class=\"tag-green\">green</span>, drops are <span class=\"tag-red\">red</span>.</p>\n        </div>\n      </div>\n    </section>\n\n    <!-- SHARED CONTROLS -->\n    <section id=\"controls\">\n      <h2>Shared controls</h2>\n      <h3>The date-range picker</h3>\n      <p>Most pages carry a date-range button at the top-right (for example\n      <code>2026-04-13 ~ 2026-07-11</code>). Every figure on the page is calculated <i>for that period</i>,\n      so this is the single most important control in the app.</p>\n      <ol class=\"steps\">\n        <li>Click the date button to open the picker.</li>\n        <li>Pick a quick <b>preset</b> — Today, Yesterday, Last 7 / 30 / 90 days, or This month — or click two days on the calendar for a custom span.</li>\n        <li>Press <b>Apply</b>. The whole page reloads for the new period.</li>\n      </ol>\n      <h3>Searching, filtering &amp; sorting</h3>\n      <p>On the sheet pages you can type in the <b>Search</b> box to match a buyer or campaign code,\n      use the <b>destination / campaign</b> dropdown to narrow to one entity, and click a\n      <b>column header</b> to sort. Long lists are paged 35 rows at a time.</p>\n      <h3>Editing data</h3>\n      <p>Data is edited <b>inline</b>. On the Daily Sheet and Campaigns sheet each row has a\n      <b>pencil</b> (edit) and <b>trash</b> (delete) button. On the Buyers sheet you edit the buyer\n      code and rate directly in the cell; totals recalculate instantly.</p>\n    </section>\n\n    <!-- DASHBOARD -->\n    <section id=\"dashboard\">\n      <h2>Dashboard</h2>\n      <p>The landing page. It answers \"how are we doing this period?\" in one screen — headline numbers up\n      top, trends and rankings below. Change the date range to re-scope everything.</p>\n      <figure>\n        <img src=\"/manual-images/dashboard.webp\" alt=\"Dashboard with numbered callouts\" width=\"1600\" height=\"1812\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>The Dashboard, scoped to the last 90 days of sample data.</figcaption>\n      </figure>\n      <ul class=\"legend\">\n        <li><span class=\"badge\">1</span><div><b>Navigation sidebar</b> — jump to any page; the current page is highlighted.</div></li>\n        <li><span class=\"badge\">2</span><div><b>Date range</b> — sets the reporting period for every card and chart on the page.</div></li>\n        <li><span class=\"badge\">3</span><div><b>KPI cards</b> — Revenue (billed), Expenses, Profit and Counted Leads, plus Answer Rate, Profit Margin, Active Buyers and Active Campaigns. Each headline shows the change <i>vs. the previous period</i>.</div></li>\n        <li><span class=\"badge\">4</span><div><b>Revenue, expenses &amp; profit over time</b> — the income trend. Toggle <b>Daily / 4 Days / Weekly</b> at the top-right to change the grouping.</div></li>\n        <li><span class=\"badge\">5</span><div><b>Most active buyers</b> — your buyers ranked by revenue for the period.</div></li>\n        <li><span class=\"badge\">6</span><div><b>Answered vs missed Leads</b> — Lead-quality trend on the buyer side; a healthy chart hugs the top (answered) line.</div></li>\n        <li><span class=\"badge\">7</span><div><b>Top traffic sources</b> — campaign spend broken down by traffic source.</div></li>\n      </ul>\n      <div class=\"callout\"><span class=\"h\">Reading the KPIs</span>\n        <p>A red <b>Profit</b> or negative <b>Profit Margin</b> means cost outran revenue for the selected\n        window — open the <a href=\"#complete-report\">Complete Report</a> to see exactly which destinations drove it.</p>\n      </div>\n    </section>\n\n    <!-- DAILY SHEET -->\n    <section id=\"daily-sheet\">\n      <h2>Daily Sheet</h2>\n      <p>Your day-to-day workhorse for the <b>revenue</b> side. Each row is one destination's Leads for one\n      day. The <b>Total</b> column and the navy totals bar update automatically from Counted × Rate.</p>\n      <figure>\n        <img src=\"/manual-images/daily-sheet.webp\" alt=\"Daily Sheet with numbered callouts\" width=\"1600\" height=\"1638\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>The Daily Sheet — buyer Lead records for the selected period.</figcaption>\n      </figure>\n      <ul class=\"legend\">\n        <li><span class=\"badge\">1</span><div><b>Search</b> — filter rows by destination code (e.g. type <code>RTG</code>).</div></li>\n        <li><span class=\"badge\">2</span><div><b>Date</b> — the reporting period, shared with the rest of the app.</div></li>\n        <li><span class=\"badge\">3</span><div><b>Destination</b> — narrow the sheet to a single destination, or leave on <i>All destinations</i>.</div></li>\n        <li><span class=\"badge\">4</span><div><b>Column headers</b> — Date, Destination, Answered, Missed, Replacement, Counted, Rate, Total. Click a header (e.g. <b>Rate ↓</b>) to sort by it.</div></li>\n        <li><span class=\"badge\">5</span><div><b>Row actions</b> — the <b>pencil</b> edits a record; the <b>trash</b> deletes it (with a confirm).</div></li>\n        <li><span class=\"badge\">6</span><div><b>Totals &amp; pagination</b> — the navy <b>TOTAL</b> bar sums the filtered set; use <b>Prev / Next</b> to page through 35 rows at a time.</div></li>\n      </ul>\n      <div class=\"callout\"><span class=\"h\">Entering a day's numbers</span>\n        <p>Add or correct records inline on the sheet, then move on — the buyer's Total and every summary\n        that references it (Dashboard, Buyers, Complete Report) update the next time you open them.</p>\n      </div>\n    </section>\n\n    <!-- BUYERS -->\n    <section id=\"buyers\">\n      <h2>Buyers</h2>\n      <p>A rolled-up <b>monthly sheet</b>, one row per buyer, for the selected date range. It's the quickest\n      way to see how much each customer bought and to keep their <b>rate</b> current.</p>\n      <figure>\n        <img src=\"/manual-images/buyers.webp\" alt=\"Buyers monthly sheet\" width=\"1600\" height=\"1234\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Buyers — per-buyer totals with inline-editable rates.</figcaption>\n      </figure>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Buyers</b></td><td>The buyer code. Editable — rename a buyer inline.</td></tr>\n          <tr><td><b>Total Leads Bought</b></td><td>Auto-summed from the Daily Sheet for the chosen date range.</td></tr>\n          <tr><td><b>Average Leads a Day</b></td><td>Total Leads divided by the active days in the period.</td></tr>\n          <tr><td><b>Rates</b></td><td>Price per Lead. <b>Editable</b> — click the cell and type a new value.</td></tr>\n          <tr><td><b>Amount Received</b></td><td>Calculated automatically (Leads × rate).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout note\"><span class=\"h\">Where do new buyers come from?</span>\n        <p>A buyer appears here automatically the first time its code is used on the Daily Sheet — there's no\n        separate \"add buyer\" step. Use the <b>Search by name</b> box to find one quickly.</p>\n      </div>\n    </section>\n\n    <!-- CAMPAIGNS -->\n    <section id=\"campaigns\">\n      <h2>Campaigns</h2>\n      <p>The mirror image of the Daily Sheet, for the <b>cost</b> side. Each row is a campaign's Leads for one\n      day at a given traffic destination. This is where your media-buying spend is recorded.</p>\n      <figure>\n        <img src=\"/manual-images/campaigns.webp\" alt=\"Campaigns sheet\" width=\"1600\" height=\"1638\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Campaigns — campaign Lead records (the cost / billing sheet).</figcaption>\n      </figure>\n      <p>The controls match the Daily Sheet: <b>Search</b> by campaign code, a <b>Date</b> range, a\n      <b>Campaign</b> dropdown, sortable headers, per-row edit / delete, a navy <b>TOTAL</b> bar and paging.\n      The extra <b>Destination</b> column names the traffic source the campaign was buying.</p>\n      <div class=\"callout\"><span class=\"h\">Revenue vs. cost at a glance</span>\n        <p>Daily Sheet totals are your money <i>in</i>; Campaigns totals are your money <i>out</i>. The\n        <a href=\"#complete-report\">Complete Report</a> subtracts one from the other for you.</p>\n      </div>\n    </section>\n\n    <!-- VENDORS -->\n    <section id=\"vendors\">\n      <h2>Vendors</h2>\n      <p>A running <b>payment ledger for each traffic source</b>. The page opens with one <b>tab per traffic\n      source</b> — the same sources you buy on the <a href=\"#campaigns\">Campaigns</a> sheet (e.g. <code>DXTST</code>,\n      <code>RGR</code>) — so you can track, per vendor, how many Leads converted, what that comes to, and how much\n      has actually been paid.</p>\n      <figure>\n        <img src=\"/manual-images/vendors.webp\" alt=\"Vendors page showing the DXTST payment ledger\" width=\"2400\" height=\"1304\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Vendors — the DXTST tab: a dated ledger with auto Payments, an Average Leads a day, and the automatic colour-coded Due / Advance balance.</figcaption>\n      </figure>\n      <h3>Tabs &amp; the shared date filter</h3>\n      <p>Click a tab along the top to switch vendors. The <b>+</b> tab adds a vendor that isn't in Campaigns —\n      type its name and it behaves exactly like the rest. One <b>date-range picker</b> at the top-right applies to\n      <i>every</i> tab at once: change it and each vendor's rows and totals re-scope to that period.</p>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Date</b></td><td>The day the entry is for — one row per day you record.</td></tr>\n          <tr><td><b>Traffic Source</b></td><td>Filled in for you — always the current tab's vendor.</td></tr>\n          <tr><td><b>Converted Lead</b></td><td>How many Leads converted that day. You type this.</td></tr>\n          <tr><td><b>Price (Usd)</b></td><td>Price per converted Lead, in dollars. You type this; new rows pre-fill the last price used.</td></tr>\n          <tr><td><b>Payments</b></td><td>Calculated automatically as <code>Converted Lead × Price</code>. You never type this.</td></tr>\n          <tr><td><b>Amount paid</b></td><td>How much has actually been paid for that day. You type this.</td></tr>\n        </tbody>\n      </table>\n      <h3>Adding &amp; editing rows</h3>\n      <ol class=\"steps\">\n        <li>On the bottom (blank) row, set the <b>Date</b>, then type the <b>Converted Lead</b> count, the <b>Price</b>, and any <b>Amount paid</b>.</li>\n        <li>Press <kbd>Enter</kbd> or click the <b>+</b> at the end of the row to save it.</li>\n        <li>Edit any saved row in place — changes save when you click away; the <b>trash</b> icon removes a row.</li>\n      </ol>\n      <h3>The figures below the sheet</h3>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>Average Leads a Day</h3><p>Total converted Leads ÷ the number of <b>days worked</b> — the days in the period that actually recorded converted Leads. It matches how the <a href=\"#buyers\">Buyers</a> sheet works, so the two pages read the same way.</p></div>\n        <div class=\"card\"><h3>Initial Advance</h3><p>The balance the period <b>opens</b> with. You type it once, on your earliest period; after that it <b>carries forward</b> on its own — every new period opens at whatever the previous one closed at, so changing the date range can never throw the figure off. A negative number means the period opened with money owed to the vendor.</p></div>\n        <div class=\"card\"><h3>Amount Due / Advance</h3><p>Worked out for you as <code>Initial Advance + Amount paid − Payments</code>. Positive means the vendor is holding your money, so it reads <span class=\"tag-green\">Advance</span>; negative means you still owe them and it reads <span class=\"tag-red\">Due</span>. There is nothing to pick — the label always follows the figures.</p></div>\n      </div>\n      <div class=\"callout\"><span class=\"h\">Payments vs. Amount paid</span>\n        <p><b>Payments</b> is what the Leads come to (Leads × price); <b>Amount paid</b> is what has actually been\n        settled. The navy <b>Total</b> bar sums Converted Leads, Payments and Amount paid for the period.</p>\n      </div>\n    </section>\n\n    <!-- PORTAL EXPENSES -->\n    <section id=\"portal-expenses\">\n      <h2>Portal Expenses</h2>\n      <p>A <b>monthly expense sheet</b>, one row per provider, for what you spend running the calling portals.\n      Pick a month with the selector at the top-right; the sheet and its charts are for that month.</p>\n      <figure>\n        <img src=\"/manual-images/portal-expenses.webp\" alt=\"Portal Expenses monthly sheet with charts\" width=\"2400\" height=\"1433\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Portal Expenses — the monthly sheet, per-metric provider charts and the month's Total Expenses band.</figcaption>\n      </figure>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Name</b></td><td>The provider / expense line. Type to add or rename.</td></tr>\n          <tr><td><b>Voice Minutes · Rejected Leads · Rent values · Call Recording (USD) · Voip Shield (USD) · Other expenses (USD)</b></td><td>The component amounts that make up the bill. You type each — numbers only. <b>Other expenses</b> is the catch-all for everything left over (payout, fixed float, …).</td></tr>\n          <tr><td><b>Total Amount (Usd)</b></td><td>Defaults to the sum of the component columns, but you can <b>override</b> it for a flat fee.</td></tr>\n          <tr><td><b>% of Total</b></td><td>That row's share of the month's grand total — calculated for you.</td></tr>\n        </tbody>\n      </table>\n      <p>Rows auto-save when you click away, and the bottom row adds a new provider. Below the sheet, a per-metric\n      chart panel compares providers and a navy band shows the month's <b>Total Expenses</b>.</p>\n      <div class=\"callout note\"><span class=\"h\">Auto total, with an override</span>\n        <p>Leave <b>Total Amount</b> alone and it tracks the component columns; type a value to pin a flat\n        amount (e.g. a fixed fee) independent of them.</p>\n      </div>\n    </section>\n\n    <!-- COMPLETE REPORT -->\n    <section id=\"complete-report\">\n      <h2>Complete Report</h2>\n      <p>The bottom line. Three stacked sections for the selected period: <b>Revenue</b> by buyer destination,\n      <b>Cost</b> by campaign destination, and a <b>Complete</b> summary that does the subtraction.</p>\n      <figure>\n        <img src=\"/manual-images/complete-report.webp\" alt=\"Complete Report page\" width=\"1600\" height=\"1582\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Complete Report — revenue and cost combined into profit.</figcaption>\n      </figure>\n      <p>Read it top to bottom, following the three labelled bands on the page:</p>\n      <table class=\"def\">\n        <thead><tr><th>Section</th><th>What it shows</th></tr></thead>\n        <tbody>\n          <tr><td><b>REVENUE</b><br><span style=\"color:var(--muted)\">buyer destinations</span></td><td>Every buyer's answered, missed, counted and total bill, ending in a navy total row.</td></tr>\n          <tr><td><b>COST</b><br><span style=\"color:var(--muted)\">campaign destinations</span></td><td>The same breakdown for your campaigns — money spent to source the Leads.</td></tr>\n          <tr><td><b>COMPLETE</b><br><span style=\"color:var(--muted)\">revenue − cost = profit</span></td><td>Three summary cards. When cost exceeds revenue the Profit card turns <span class=\"tag-red\">red</span> and shows a negative figure.</td></tr>\n        </tbody>\n      </table>\n      <p>Use the date range at the top-right to run the report for any month, quarter or custom window.</p>\n    </section>\n\n    <!-- ATTENDANCE -->\n    <section id=\"attendance\">\n      <h2>Attendance</h2>\n      <p>Tracks team <b>check-in / check-out</b>, fed by a Telegram bot. Staff clock in and out from Telegram;\n      this page turns that into daily rosters and per-member reports.</p>\n      <figure>\n        <img src=\"/manual-images/attendance.webp\" alt=\"Attendance page\" width=\"1600\" height=\"522\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Attendance — the Daily Roster tab with its summary cards.</figcaption>\n      </figure>\n      <h3>Three tabs</h3>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>Daily Roster</h3><p>Who's online now, plus cards for <b>Present Today</b>, <b>Still Checked In</b>, <b>Avg Hours Worked</b>, <b>Absent</b> and <b>Break Overages</b>, and a searchable table of the day's check-ins.</p></div>\n        <div class=\"card\"><h3>Staff Summary &amp; Reports</h3><p>Per-member hours over a period, with <b>XLSX</b> and <b>PDF</b> export buttons for a team sheet, an all-members report, or a single member's daily breakdown.</p></div>\n      </div>\n      <h3>Late and early marks</h3>\n      <p>Where a person has <b>expected hours</b> set on <a href=\"#staff\">Staff Management</a>, their clock\n      times are marked here: a login after their expected login reads <span class=\"tag-red\">9:07 AM 7m late</span>,\n      and a logout before their expected logout <span class=\"tag-red\">5:37 PM 23m early</span>. Hover the mark to\n      see the time it was judged against.</p>\n      <p>Anyone with <b>no</b> expected hours set is never marked — a blank schedule means \"not expected at any\n      particular hour\", not \"always on time\". The one exception is the <b>Late check-ins</b> card, which falls back\n      to 9:00 AM for people without a schedule, as it always has.</p>\n      <h3>The flag on a day</h3>\n      <p>Those same two marks are also read as <b>one verdict per day</b>, in a <b>Flag</b> column: a day is\n      <span class=\"tag-green\">On time</span>, <span class=\"tag-amber\">Late in</span>,\n      <span class=\"tag-amber\">Early out</span>, or — when it missed <b>both</b> ends —\n      <span class=\"tag-red\">Late + early</span>. The number of exclamation marks on the badge is the number of\n      marks that fired, so the doubly-bad day is findable without reading a word; hover it for the minutes\n      behind it. A day nobody clocked in for is left blank rather than called on time. As with the individual\n      marks, a logout is only judged where <b>Expected Logout</b> is set, while a login on this page falls back\n      to 9:00 AM — so set both on <a href=\"#staff\">Staff</a> and the flag reads the same on every page.</p>\n      <p>The same flag appears on the <b>Daily Roster</b> table, in the <b>Off schedule</b> card above it, on\n      <a href=\"#staff\">Complete Attendance</a>, and in <b>Staff Summary</b>, where the month is counted per\n      person as <b>On time / Late in / Early out / Both</b> columns. Click a person for their day-by-day list,\n      each day carrying its own flag.</p>\n      <div class=\"callout note\"><span class=\"h\">Corrections show here too</span>\n        <p>If a day is corrected on <a href=\"#staff\">Staff Management → Complete Attendance</a>, this page shows the\n        corrected figures — the hours, the break, the late and early marks, and who counts as still checked in. The\n        two pages read the same record, so they can never disagree.</p>\n      </div>\n      <div class=\"callout warn\"><span class=\"h\">Needs the attendance service</span>\n        <p>Attendance data is supplied by the external Telegram check-in bot. On an install where that bot and\n        its tables aren't set up yet, the roster reads <i>\"Nobody checked in yet today\"</i> and the counts stay\n        at zero — the check-in and summary features light up once the bot is connected.</p>\n      </div>\n    </section>\n\n    <!-- QUEUES -->\n    <section id=\"queues\">\n      <h2>Queues</h2>\n      <p>Who covers which queues. Two sheets in one page — <b>Forwarding Queues</b> and\n      <b>Camp &amp; Flow Queues</b> — switched with the tabs at the top. They work identically and keep\n      completely separate rows, so the same person can hold a row on both.</p>\n      <figure>\n        <img src=\"/manual-images/queues.webp\" alt=\"Queues page showing the Forwarding Queues sheet\" width=\"1600\" height=\"1000\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Queues — the Forwarding Queues sheet, with each person's codes as draggable chips and the navy TOTAL row beneath.</figcaption>\n      </figure>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Sr. No.</b></td><td>Just the row's position. It renumbers itself and is never stored.</td></tr>\n          <tr><td><b>Name</b></td><td>Picked from the <a href=\"#staff\">Staff</a> roster — you cannot type a free-text name here, which is what keeps every sheet in the app using one spelling.</td></tr>\n          <tr><td><b>Queues</b></td><td>The person's queue codes, shown as chips. Add one from the picker; click a chip's <b>×</b> to remove it.</td></tr>\n          <tr><td><b>Total</b></td><td>How many queues that person covers — counted for you.</td></tr>\n        </tbody>\n      </table>\n      <h3>Reordering by dragging</h3>\n      <p>Queues are worked in order, so the chips can be <b>dragged</b> into the order you want rather than\n      deleted and re-added. Press and hold a chip, drag it along the row, and let go where it belongs. It works\n      the same way with a finger on a phone or tablet.</p>\n      <div class=\"callout\"><span class=\"h\">Adding people and codes</span>\n        <p>The bottom row adds a person. A queue code that doesn't exist yet is created the first time you use it,\n        and the code list is <b>shared by both sheets</b>. Use the <b>PDF</b> button to print the sheet as it stands.</p>\n      </div>\n    </section>\n\n    <!-- REVIEW -->\n    <section id=\"review\">\n      <h2>Review</h2>\n      <p>Monthly staff reviews, in three tabs: <b>Performance</b>, <b>Behaviour</b> and <b>Departments</b>.\n      Rows are grouped under the department each person belongs to, and those departments come from\n      <a href=\"#staff\">Staff Management</a>.</p>\n      <figure>\n        <img src=\"/manual-images/review.webp\" alt=\"Review page, Performance tab, grouped into department bands\" width=\"1600\" height=\"1000\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Review — the Performance tab. Note the heading: the sheet is <b>Reviewing August 2026</b>, the month before it was written.</figcaption>\n      </figure>\n      <div class=\"callout note\"><span class=\"h\">A review is about the month before it</span>\n        <p>A sheet you fill in during <b>September</b> is judging <b>August's</b> work. That is why the month\n        selector opens on <b>last month</b> and the heading names the month being judged — so there is never any\n        doubt which month a score belongs to. The same applies to <a href=\"#staff\">Salaries</a>: a salary paid in\n        September is for August.</p>\n      </div>\n      <table class=\"def\">\n        <thead><tr><th>Tab</th><th>What it records</th></tr></thead>\n        <tbody>\n          <tr><td><b>Performance</b></td><td>A rating and a percentage per person, plus free-text <b>Notes</b>.</td></tr>\n          <tr><td><b>Behaviour</b></td><td>The same shape, kept separately so conduct and output are not mixed.</td></tr>\n          <tr><td><b>Departments</b></td><td>One score for each department as a whole, for that month.</td></tr>\n        </tbody>\n      </table>\n      <p>Everything saves as you type. Each tab has its own <b>PDF</b> export, and long notes wrap inside their\n      column so the table keeps its shape.</p>\n    </section>\n\n    <!-- STAFF MANAGEMENT -->\n    <section id=\"staff\">\n      <h2>Staff Management</h2>\n      <p>The <b>one roster</b> that Queues and Review both pick their names from, plus the three sheets that\n      hang off it. Four tabs: <b>Staff</b>, <b>Complete Attendance</b>, <b>Leaves</b> and <b>Salaries</b>.</p>\n      <figure>\n        <img src=\"/manual-images/staff.webp\" alt=\"Staff Management, the Staff roster tab\" width=\"1600\" height=\"1000\" loading=\"lazy\" decoding=\"async\" />\n        <figcaption>Staff Management — the roster. Departments are a tick-list, Status is colour-coded, and the two Expected columns are the hours the attendance pages judge a day against. The last two people have none set, so nothing of theirs is ever marked.</figcaption>\n      </figure>\n      <h3>Staff</h3>\n      <p>Add, rename and remove people, and set what each one is.</p>\n      <table class=\"def\">\n        <thead><tr><th>Column</th><th>Meaning</th></tr></thead>\n        <tbody>\n          <tr><td><b>Name</b></td><td>Add one, or paste a whole list at once to seed a team.</td></tr>\n          <tr><td><b>Departments</b></td><td>A tick-list, not a dropdown — somebody can belong to <b>several</b>. This is what groups them on the Review page.</td></tr>\n          <tr><td><b>Expected Login / Expected Logout</b></td><td>The hours they are expected to keep. Both attendance pages mark a late login and an early logout against these. <b>Leave them blank</b> for anyone without set hours — blank means nothing of theirs is ever marked.</td></tr>\n          <tr><td><b>Status</b></td><td><span class=\"tag-green\">Active</span>, <span class=\"tag-red\">Inactive</span> or Leave, colour-coded so the column reads at a glance.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout warn\"><span class=\"h\">Renaming affects attendance</span>\n        <p>A person's check-in account is matched to them <b>by name</b> — it is never picked. Renaming somebody\n        re-matches it, so if a new spelling no longer matches the name their check-in bot uses, their attendance\n        stops arriving automatically and has to be keyed in by hand. If someone's days go missing after a rename,\n        that is why; put the spelling back.</p>\n      </div>\n      <h3>Complete Attendance</h3>\n      <p>One day at a time — the date selector opens on <b>today</b>, because this records a day as it happens.\n      Every person on the roster gets a row.</p>\n      <p><b>Every row is editable</b>, whether or not the check-in bot recorded that day. A day the bot recorded\n      arrives filled in; the moment you change anything, your version <b>replaces</b> it and the\n      <a href=\"#attendance\">Attendance</a> page shows your figures too. Corrected rows are tinted\n      <b>amber</b>, and the arrow at the end of the row puts the bot's original record back — the bot's own data is\n      never overwritten, which is what makes that possible.</p>\n      <p>People the bot never saw get an empty row that saves itself on the first edit, so opening a roster of\n      thirty does not create thirty blank records. Hours are worked out from the clock times as you type.</p>\n      <p>The <b>Flag</b> column gives each row the day&rsquo;s verdict —\n      <span class=\"tag-green\">On time</span>, <span class=\"tag-amber\">Late in</span>,\n      <span class=\"tag-amber\">Early out</span> or <span class=\"tag-red\">Late + early</span> — against that\n      person&rsquo;s own expected hours, and it moves as you type a correction. The card heading counts the day up,\n      and the <b>PDF</b> export carries the same column. Read the <a href=\"#attendance\">Attendance</a> page for\n      how the verdict is decided; it is decided identically on both pages.</p>\n      <p>Above the table, five <b>scorecards</b> count the day being shown — <b>In</b> out of the roster, then\n      <b>On time</b>, <b>Late in</b>, <b>Early out</b> and <b>Late + early</b> out of the days that could be\n      judged. They are counted from the very rows on screen, so a card can never disagree with the column\n      beneath it.</p>\n      <p>The <b>Status</b> column shows what is stored for that day. Where nothing is stored yet it shows what\n      the clock times mean, in <i>grey italics</i>: <b>absent</b> for a row with no login, <b>still in</b> for\n      somebody who has logged in but not out, <b>present</b> once they have. Pick a status yourself and it is\n      stored and stops being grey.</p>\n      <div class=\"callout note\"><span class=\"h\">The date is New York&rsquo;s, and Refresh re-reads it</span>\n        <p>Attendance days are days as the <b>New York</b> office reckons them, not your own timezone &mdash; so\n        this tab opens on <i>their</i> today, and if you leave it open past their midnight it moves on to the new\n        day by itself. The check-in bot keeps writing logins and logouts while you sit there, so hit\n        <b>Refresh</b> to pull the day again; the heading says how old the figures on screen are.</p>\n      </div>\n      <h3>Leaves &amp; Salaries</h3>\n      <p><b>Leaves</b> records sick leave, break leave, half days, late logins and anything else, per person per\n      day. <b>Salaries</b> is one row per person per month — status, amount and a note.</p>\n      <p>Both are monthly sheets about the month just finished, so like Review they open on <b>last month</b>.\n      Every tab has its own <b>PDF</b> export.</p>\n    </section>\n\n    <!-- AUTH -->\n    <section id=\"auth\">\n      <h2>Accounts &amp; access (optional)</h2>\n      <p>Platform-CRM can run fully open (no login) or with authentication switched on. When it's enabled you\n      sign in with your email and a 6-digit code from the <b>Google Authenticator</b> app — there's no password\n      to remember or leak.</p>\n      <div class=\"grid2\">\n        <div class=\"card\"><h3>Signing in</h3><p>Enter your email, then the current 6-digit code from your authenticator app. First-time users scan a QR enrolment link an admin sends them.</p></div>\n        <div class=\"card\"><h3>Admin extras</h3><p>Admins get two more sidebar items — <b>Users</b> (create accounts, set per-page access, reset authenticators) and <b>System Logs</b> (a searchable audit trail of who did what).</p></div>\n      </div>\n      <div class=\"callout note\"><p>These items only appear when authentication is enabled and you have the rights to see them. If you don't see <b>Users</b> or <b>System Logs</b>, your install is either open or your account isn't an admin — that's expected.</p></div>\n    </section>\n\n    <!-- FAQ -->\n    <section id=\"faq\">\n      <h2>Tips &amp; FAQ</h2>\n      <h3>My numbers look tiny / empty</h3>\n      <p>Almost always the <b>date range</b>. The default window can be a single quiet day — widen it (try\n      <b>Last 90 days</b>) and the charts and totals fill in.</p>\n      <h3>I changed a rate but the Dashboard didn't move</h3>\n      <p>Summary pages load their figures when you open them. Revisit the Dashboard or Complete Report after an\n      edit and it will reflect the new numbers.</p>\n      <h3>A total looks wrong</h3>\n      <p>Totals are always <code>Counted × Rate</code> summed across the <i>filtered</i> rows. Check that your\n      search box and destination filter aren't hiding rows, and that the date range is what you expect.</p>\n      <h3>How do I remove a record?</h3>\n      <p>On the Daily Sheet or Campaigns sheet, click the <b>trash</b> icon at the end of the row and confirm.</p>\n      <h3>Somebody's attendance stopped arriving</h3>\n      <p>Almost always a <b>name</b>. A person's check-in account is matched to them by name alone, so if their\n      name on <a href=\"#staff\">Staff</a> was edited and no longer matches the one their check-in bot uses, their\n      days stop coming through. Put the spelling back and they reappear.</p>\n      <h3>Nobody is being marked late</h3>\n      <p>Expected hours have to be set first, on <a href=\"#staff\">Staff Management → Staff</a>. Until a person has\n      an Expected Login, nothing of theirs is marked — that is deliberate, so nobody is called late against hours\n      that were never agreed with them.</p>\n      <h3>Which month does a review or salary belong to?</h3>\n      <p>The month <b>before</b> the one you fill it in. Both pages open on last month and name the month being\n      judged in the heading, so go by that rather than today's date.</p>\n    </section>\n\n    <footer>\n      Platform-CRM User Manual · Revised 10 Sep 2026 · Screens captured from sample data on 11 Jul 2026.<br>\n      A pay-per-Lead / Lead-forwarding CRM — Dashboard, Daily Sheet, Buyers, Campaigns, Vendors, Portal Expenses, Complete Report, Attendance, Queues, Review &amp; Staff Management.\n    </footer>\n  </main>\n</div>"

export default function UserManual() {
  return (
    <div className="manual-page">
      <style dangerouslySetInnerHTML={{ __html: CSS }} />
      <Link to="/" className="manual-back" aria-label="Close user manual">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>
        Close
      </Link>
      <div dangerouslySetInnerHTML={{ __html: BODY }} />
    </div>
  )
}
